function c=task5b_load_config(folder)
% Generated by the active C++ WBMpcInterface getters, including defaults.
frozen=jsondecode(fileread(fullfile(pwd,'config/loaded_configuration.json')));
if nargin==0,folder=fullfile(pwd,'config');end
actual=jsondecode(fileread(fullfile(folder,'loaded_configuration.json')));
assert(isequaln(actual,frozen),'Task5B:ConfigMismatch','Active C++ configuration differs from the teaching configuration.');
c=numericFields(actual);assert(c.state_dim==58 && c.input_dim==35);
assert(numel(c.joint_names_mpc_order)==23);c.origin='Actual C++ WBMpcInterface / accepted task.info';
end
function s=numericFields(s)
if isstruct(s)
 for j=1:numel(s),names=fieldnames(s(j));for k=1:numel(names),s(j).(names{k})=numericFields(s(j).(names{k}));end,end
elseif iscell(s)
 for j=1:numel(s),s{j}=numericFields(s{j});end
elseif ischar(s)
 n=str2double(s);if ~isnan(n),s=n;elseif strcmp(s,'true'),s=true;elseif strcmp(s,'false'),s=false;end
end
end
